using System.Net;
using System.Net.Sockets;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real local HTTP server standing in for the provider; records what it receives.</summary>
internal sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public FakeProvider(HttpStatusCode status, string body, string contentType = "application/json")
    {
        var port = FreePort();
        BaseAddress = new Uri($"http://localhost:{port}");
        listener.Prefixes.Add($"http://localhost:{port}/");
        listener.Start();
        loop = Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            Received = new ReceivedRequest(
                context.Request.HttpMethod,
                context.Request.Url!.AbsolutePath,
                context.Request.ContentType,
                await reader.ReadToEndAsync());
            var bytes = Encoding.UTF8.GetBytes(body);
            context.Response.StatusCode = (int)status;
            context.Response.ContentType = contentType;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        });
    }

    public Uri BaseAddress { get; }

    public ReceivedRequest? Received { get; private set; }

    public void Dispose()
    {
        listener.Close();
        try { loop.Wait(TimeSpan.FromSeconds(1)); } catch (AggregateException) { }
    }

    private static int FreePort()
    {
        var tcp = new TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }
}

internal sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);
