public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, ReceivedRequest Sent)> Authorize(
        HttpStatusCode status, string body, string reference = "ORD-7", decimal amount = 12.5m, string currency = "eur")
    {
        using var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);
        return (outcome, provider.Received!);
    }

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        var (_, sent) = await Authorize(HttpStatusCode.OK, """{"status":"approved"}""");

        Assert.Equal("POST", sent.Method);
        Assert.Equal("/v1/authorizations", sent.Path);
        Assert.StartsWith("application/json", sent.ContentType);
        using var json = JsonDocument.Parse(sent.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Authorize(HttpStatusCode.OK, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(HttpStatusCode.OK, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_with_an_unknown_status_is_not_treated_as_approved()
    {
        var (outcome, _) = await Authorize(HttpStatusCode.OK, """{"status":"pending"}""");

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_is_read_as_declined()
    {
        var (outcome, _) = await Authorize(HttpStatusCode.PaymentRequired, """{"error":"insufficient_funds"}""");

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(HttpStatusCode.BadRequest)]
    [InlineData(HttpStatusCode.Unauthorized)]
    [InlineData(HttpStatusCode.InternalServerError)]
    public async Task Other_failures_are_raised_rather_than_read_as_a_decision(HttpStatusCode status)
    {
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_raised()
    {
        await Assert.ThrowsAnyAsync<Exception>(() => Authorize(HttpStatusCode.OK, "<html>oops</html>"));
    }
}
